changes.before:
/* =====================================================
   CONTRACT DTG — PAGE-SPECIFIC STYLES
   ----------------------------------------------------------
   The shared editorial chrome (design tokens, top bar, hero,
   calculator shell, result panel, totals, buttons, pricing-table
   base, contact card, footer, toast, pricing-error, and the entire
   AI chat panel) lives in:
     /shared_components/css/contract-pricing-2026.css
   which is loaded BEFORE this file, so the rules below win the
   cascade where they overlap.

   Only the DTG-specific input components live here:
     · Location checkbox grid (.loc*)       — LC / FF / FB / JF / JB
     · Heavyweight toggle (.hw-toggle*)
     · Per-piece breakdown card (.pp-breakdown*)
     · Per-location pricing-table extras: tfoot qty-col highlight +
       the "effective rate" row (table.price tfoot tr.effective-row)
   ===================================================== */

/* Location checkbox grid */
.loc-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
}

.loc {
    position: relative;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 12px;
    background: var(--paper-2);
    border: 1px solid var(--line);
    border-radius: var(--r);
    cursor: pointer;
    transition: all 140ms;
}

.loc:hover {
    border-color: var(--pink-300);
    background: var(--paper);
}

.loc input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.loc-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 1px;
}

.loc-name {
    font-size: 14px;
    font-weight: 600;
    color: var(--ink);
}

.loc-size {
    font-family: var(--mono);
    font-size: 11px;
    color: var(--slate-2);
    letter-spacing: 0.02em;
}

.loc-check {
    width: 24px;
    height: 24px;
    border-radius: 6px;
    border: 1.5px solid var(--slate-3);
    background: var(--paper);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: transparent;
    flex: 0 0 24px;
    transition: all 140ms;
}

.loc.is-selected {
    border-color: var(--pink-500);
    background: linear-gradient(135deg, var(--pink-50) 0%, var(--paper) 100%);
    box-shadow: 0 0 0 1px var(--pink-300) inset;
}

.loc.is-selected .loc-check {
    background: var(--pink-600);
    border-color: var(--pink-600);
    color: var(--color-on-brand);
}

/* Heavyweight toggle — clearly interactive card with a prominent switch. */
.hw-toggle {
    position: relative;
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 14px 16px;
    background: var(--paper-2);
    border: 1px solid var(--line);
    border-radius: var(--r);
    cursor: pointer;
    transition: all 160ms;
    user-select: none;
}

.hw-toggle:hover {
    border-color: var(--pink-300);
    background: var(--paper);
}

.hw-toggle input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.hw-switch {
    width: 48px;
    height: 28px;
    background: var(--slate-3);
    border-radius: 999px;
    position: relative;
    transition: background 200ms;
    flex: 0 0 48px;
    box-shadow: inset 0 1px 2px rgb(0 0 0 / 8%);
}

.hw-switch::after {
    content: "";
    position: absolute;
    top: 3px;
    left: 3px;
    width: 22px;
    height: 22px;
    background: var(--color-surface);
    border-radius: 50%;
    transition: transform 200ms;
    box-shadow: 0 1px 3px rgb(0 0 0 / 20%);
}
.hw-toggle input:checked + .hw-switch { background: var(--pink-600); }
.hw-toggle input:checked + .hw-switch::after { transform: translateX(20px); }

.hw-text {
    display: flex;
    flex-direction: column;
    gap: 3px;
    flex: 1;
}

.hw-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.2;
}

.hw-sub {
    font-family: var(--mono);
    font-size: 12px;
    color: var(--slate);
    letter-spacing: 0.01em;
}

/* "On" state — pink-tinted card matches the location-card selected style.
   JS adds .is-on whenever the checkbox flips so the whole card lights up,
   not just the switch — same affordance pattern as .loc.is-selected. */
.hw-toggle.is-on {
    border-color: var(--pink-500);
    background: linear-gradient(135deg, var(--pink-50) 0%, var(--paper) 100%);
    box-shadow: 0 0 0 1px var(--pink-300) inset;
}
.hw-toggle.is-on .hw-sub { color: var(--pink-700); }

/* Keyboard focus rings — the location cards and HW toggle wrap a
   visually-hidden checkbox, so key off :focus-within (the real focus
   target is the inner input). WCAG 2.4.7. */
.loc:focus-within,
.hw-toggle:focus-within {
    outline: 2px solid var(--pink-600);
    outline-offset: 2px;
    border-color: var(--pink-300);
}

/* Per-piece breakdown card — itemizes every component of the unit price
   (each location, heavyweight, LTM-per-piece) so the customer can see
   exactly what $X.XX/pc is buying. Sits between the unit-sub line and
   the Order Total card. Soft-translucent white over the pink gradient. */
.pp-breakdown {
    margin: 18px 0;
    background: rgb(255 255 255 / 75%);
    border: 1px solid rgb(185 28 92 / 18%);
    border-radius: var(--r);
    padding: 12px 14px;
}

.pp-breakdown-head {
    font-family: var(--mono);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.10em;
    text-transform: uppercase;
    color: var(--pink-700);
    margin-bottom: 8px;
}

.pp-breakdown-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 6px;
}

.pp-breakdown-list li {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    font-size: 13px;
    color: var(--ink-2);
}

.pp-breakdown-list li .pp-label {
    flex: 1;
    min-width: 0;
}

.pp-breakdown-list li .pp-sublabel {
    display: block;
    font-family: var(--mono);
    font-size: 10px;
    color: var(--slate-2);
    margin-top: 1px;
    letter-spacing: 0.02em;
}

.pp-breakdown-list li .pp-val {
    font-family: var(--mono);
    font-variant-numeric: tabular-nums;
    font-weight: 600;
    color: var(--ink);
    flex-shrink: 0;
}

.pp-breakdown-list li.pp-sum {
    border-top: 1px solid rgb(185 28 92 / 20%);
    padding-top: 8px;
    margin-top: 2px;
}

.pp-breakdown-list li.pp-sum .pp-label {
    font-weight: 600;
    color: var(--ink);
}

.pp-breakdown-list li.pp-sum .pp-val {
    color: var(--pink-700);
}

/* Per-location pricing table — active quantity-tier column highlight */
table.price tfoot td.qty-col {
    background: linear-gradient(180deg, var(--pink-100), var(--pink-200));
    color: var(--pink-800);
}

/* "Your effective rate" row — shows the all-in per-piece price for
   the customer's current selections, per tier column. Overrides the
   inherited uppercase/mono tfoot styling so the dollar amounts read
   like prices instead of footer labels. */
table.price tfoot tr.effective-row td {
    padding: 16px;
    background: var(--paper-2);
    border-top: 2px solid var(--pink-200);
    text-transform: none;
    letter-spacing: 0;
    font-weight: 600;
    color: var(--ink);
    text-align: center;
    font-family: var(--mono);
    font-size: 16px;
}

table.price tfoot tr.effective-row td.effective-label-cell {
    text-align: left;
    background: var(--pink-50);
    color: var(--pink-800);
    border-right: 1px solid var(--pink-200);
    display: table-cell;
    vertical-align: middle;
    line-height: 1.3;
}

.effective-label {
    display: block;
    font-family: var(--sans);
    font-size: 14px;
    font-weight: 700;
    color: var(--pink-800);
}

.effective-sublabel {
    display: block;
    margin-top: 2px;
    font-family: var(--sans);
    font-size: 11px;
    font-weight: 500;
    color: var(--slate);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.effective-cell .eff-amt {
    display: inline;
    font-size: 17px;
    font-weight: 700;
    color: var(--ink);
    letter-spacing: -0.01em;
}

.effective-cell .eff-unit {
    display: inline;
    margin-left: 3px;
    font-size: 11px;
    font-weight: 500;
    color: var(--slate);
    text-transform: lowercase;
    letter-spacing: 0;
}

table.price tfoot tr.effective-row td.cell-hi {
    background: var(--pink-600);
    color: var(--color-on-brand);
    position: relative;
}

table.price tfoot tr.effective-row td.cell-hi .eff-amt,
table.price tfoot tr.effective-row td.cell-hi .eff-unit {
    color: var(--color-on-brand);
}

table.price tfoot tr.effective-row td.cell-hi::after {
    content: "";
    position: absolute;
    inset: 0;
    border: 2px solid var(--pink-700);
    border-radius: 4px;
    pointer-events: none;
}

/* When a body row above the effective row is "row-hi" (its location
   is selected), the per-tier qty-col cell in that row already paints
   pink. Make sure the effective row's qty-col reuses our pink-600
   highlight rather than the lighter pink-100/200 gradient inherited
   from the generic tfoot.qty-col rule. */
table.price tfoot tr.effective-row td.qty-col:not(.cell-hi) {
    background: var(--pink-100);
    color: var(--pink-800);
}

/* Responsive — DTG-specific tweaks (shared chrome handles the rest) */
@media (width <= 640px) {
    table.price tfoot tr.effective-row td { padding: 12px 8px; font-size: 13px; }
    .effective-label { font-size: 13px; }
    .effective-sublabel { font-size: 10px; }
    .effective-cell .eff-amt { font-size: 15px; }
    .effective-cell .eff-unit { font-size: 10px; }
    .loc-grid { grid-template-columns: 1fr; }
}

